async function load(ok) {
  console.log("load " + ok);
  if (!ok) {
    throw new Error("bad");
  }
  return Promise.resolve("good");
}

load(false).catch((error) => console.log("caught " + error.message));
load(true).then((value) => console.log("got " + value));
console.log("sync done");
